export const PAGE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Teletorch</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{background:#000;color:#fff;font-family:Consolas,\"Courier New\",Courier,monospace;min-height:100vh;user-select:none}\nbody{display:flex;flex-direction:column;align-items:center;padding:8px 4px 16px}\n\n/* TV screen wrapper -- 4:3 aspect, max 1100px, min 320px */\n#screen-wrap{\n  position:relative;\n  width:min(calc(100vw - 8px),1100px);\n  aspect-ratio:4/3;\n  background:#111;\n  border:2px solid #333;\n  overflow:hidden;\n  cursor:crosshair;\n}\n#screen{\n  position:absolute;inset:0;\n  display:grid;\n  grid-template-columns:1fr;\n  grid-template-rows:repeat(24,1fr);\n  width:100%;height:100%;\n  font-size:clamp(6px,2.1vw,22px);\n  line-height:1;\n  overflow:hidden;\n}\n/* Each row is a single div, font-size via parent */\n.row{\n  display:flex;\n  align-items:center;\n  white-space:pre;\n  overflow:hidden;\n  font-family:inherit;\n  font-size:inherit;\n  font-style:normal;\n  padding:0 2px;\n  transition:opacity 0.1s;\n}\n.row span{letter-spacing:0;font-style:normal}\n\n/* Torch overlay -- covers the screen, pointer-events:none */\n#torch-overlay{\n  position:absolute;inset:0;\n  pointer-events:none;\n  display:none;\n  z-index:5;\n}\nbody.torch-on #torch-overlay{display:block}\n\n/* Colour classes */\n.c-white   {color:#fff}\n.c-yellow  {color:#ff0}\n.c-cyan    {color:#0ff}\n.c-green   {color:#0f0}\n.c-red     {color:#f00}\n.c-magenta {color:#f0f}\n.c-blue    {color:#4d7cff}\n\n/* Controls below the screen */\n#controls{\n  width:min(calc(100vw - 8px),1100px);\n  margin-top:8px;\n  display:flex;\n  flex-direction:column;\n  gap:8px;\n}\n\n/* Place bar */\n#place-bar{\n  display:flex;\n  gap:6px;\n  align-items:center;\n  flex-wrap:wrap;\n}\n#place-bar label{color:#0ff;font-size:clamp(10px,1.8vw,14px)}\n#place-input{\n  flex:1;min-width:120px;\n  background:#111;color:#fff;border:1px solid #444;\n  padding:4px 6px;font-family:inherit;\n  font-size:clamp(10px,1.8vw,14px);\n}\n#place-input:focus{outline:1px solid #0ff}\n#place-btn{\n  background:#111;color:#0ff;border:1px solid #0ff;\n  padding:4px 10px;cursor:pointer;font-family:inherit;\n  font-size:clamp(10px,1.8vw,14px);\n}\n#place-btn:hover{background:#0ff;color:#000}\n#place-name{color:#0f0;font-size:clamp(9px,1.6vw,13px);min-width:80px}\n\n/* Digit display + keypad row */\n#keypad-row{\n  display:flex;\n  gap:12px;\n  align-items:flex-start;\n  flex-wrap:wrap;\n}\n#digit-display{\n  font-size:clamp(18px,4vw,36px);\n  color:#ff0;letter-spacing:6px;\n  width:6ch;text-align:center;\n  border-bottom:2px solid #ff0;\n  padding:2px 4px;\n  min-width:80px;\n}\n\n/* Keypad grid */\n#keypad{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:4px;\n  width:clamp(110px,20vw,180px);\n}\n.kbtn{\n  background:#111;color:#fff;border:1px solid #555;\n  padding:clamp(4px,1vw,8px) 0;\n  cursor:pointer;font-family:inherit;\n  font-size:clamp(11px,2vw,16px);\n  text-align:center;\n}\n.kbtn:hover{background:#333}\n.kbtn:active{background:#555}\n.kbtn-back{color:#ff0;border-color:#ff0}\n.kbtn-back:hover{background:#332200}\n\n/* Sub-page arrows */\n#subpage-btns{\n  display:flex;flex-direction:column;gap:4px;\n  justify-content:center;\n}\n.spbtn{\n  background:#111;color:#fff;border:1px solid #555;\n  padding:4px 10px;cursor:pointer;font-family:inherit;\n  font-size:clamp(11px,2vw,16px);\n}\n.spbtn:hover{background:#333}\n\n/* Fastext buttons */\n#fastext-row{\n  display:flex;gap:6px;flex-wrap:wrap;\n}\n.fbtn{\n  flex:1;min-width:60px;\n  padding:clamp(4px,1vw,8px) 4px;\n  background:#111;border:none;\n  cursor:pointer;font-family:inherit;\n  font-size:clamp(10px,1.8vw,14px);\n  text-align:center;font-style:normal;\n}\n.fbtn:hover{filter:brightness(1.3)}\n.fbtn:active{filter:brightness(0.7)}\n.fbtn-red    {color:#f00;border:1px solid #f00}\n.fbtn-green  {color:#0f0;border:1px solid #0f0}\n.fbtn-yellow {color:#ff0;border:1px solid #ff0}\n.fbtn-cyan   {color:#0ff;border:1px solid #0ff}\n\n/* Torch toggle */\n#torch-row{\n  display:flex;align-items:center;gap:8px;\n}\n#torch-label{color:#888;font-size:clamp(9px,1.6vw,13px)}\n#torch-btn{\n  background:#111;color:#888;border:1px solid #444;\n  padding:3px 10px;cursor:pointer;font-family:inherit;\n  font-size:clamp(9px,1.6vw,13px);\n}\nbody.torch-on #torch-btn{color:#ff0;border-color:#ff0}\n\n/* Footer */\n#footer{\n  margin-top:8px;\n  color:#555;\n  font-size:clamp(8px,1.4vw,11px);\n  text-align:center;\n}\n#footer a{color:#4d7cff;text-decoration:none}\n#footer a:hover{text-decoration:underline}\n\n/* Aria-live hidden text */\n#a11y-text{\n  position:absolute;\n  width:1px;height:1px;\n  overflow:hidden;clip:rect(0,0,0,0);\n  white-space:pre;\n}\n</style>\n</head>\n<body>\n\n<div id=\"screen-wrap\" tabindex=\"0\" aria-label=\"Teletext screen\" role=\"region\">\n  <div id=\"screen\" aria-hidden=\"true\"></div>\n  <canvas id=\"torch-overlay\" aria-hidden=\"true\"></canvas>\n</div>\n\n<div id=\"controls\">\n  <div id=\"place-bar\">\n    <label for=\"place-input\">Place:</label>\n    <input id=\"place-input\" type=\"text\" placeholder=\"City or lat,lon\" autocomplete=\"off\" aria-label=\"Set place\">\n    <button id=\"place-btn\" aria-label=\"Set place\">Set</button>\n    <span id=\"place-name\" aria-live=\"polite\"></span>\n  </div>\n\n  <div id=\"keypad-row\">\n    <div>\n      <div id=\"digit-display\" aria-live=\"polite\" aria-label=\"Page number being typed\">---</div>\n    </div>\n    <div id=\"keypad\" role=\"group\" aria-label=\"Page number keypad\">\n      <button class=\"kbtn\" data-d=\"1\" aria-label=\"1\">1</button>\n      <button class=\"kbtn\" data-d=\"2\" aria-label=\"2\">2</button>\n      <button class=\"kbtn\" data-d=\"3\" aria-label=\"3\">3</button>\n      <button class=\"kbtn\" data-d=\"4\" aria-label=\"4\">4</button>\n      <button class=\"kbtn\" data-d=\"5\" aria-label=\"5\">5</button>\n      <button class=\"kbtn\" data-d=\"6\" aria-label=\"6\">6</button>\n      <button class=\"kbtn\" data-d=\"7\" aria-label=\"7\">7</button>\n      <button class=\"kbtn\" data-d=\"8\" aria-label=\"8\">8</button>\n      <button class=\"kbtn\" data-d=\"9\" aria-label=\"9\">9</button>\n      <button class=\"kbtn kbtn-back\" id=\"btn-back\" aria-label=\"Back/clear\">Bk</button>\n      <button class=\"kbtn\" data-d=\"0\" aria-label=\"0\">0</button>\n      <button class=\"kbtn\" id=\"btn-go\" aria-label=\"Go to page\">Go</button>\n    </div>\n    <div id=\"subpage-btns\" aria-label=\"Sub-page navigation\">\n      <button class=\"spbtn\" id=\"btn-prev\" aria-label=\"Previous sub-page\">&lt; Prev</button>\n      <button class=\"spbtn\" id=\"btn-next\" aria-label=\"Next sub-page\">Next &gt;</button>\n    </div>\n  </div>\n\n  <div id=\"fastext-row\" role=\"group\" aria-label=\"Fastext quick links\">\n    <button class=\"fbtn fbtn-red\"    id=\"ft-red\"    aria-label=\"Red fastext\">---</button>\n    <button class=\"fbtn fbtn-green\"  id=\"ft-green\"  aria-label=\"Green fastext\">---</button>\n    <button class=\"fbtn fbtn-yellow\" id=\"ft-yellow\" aria-label=\"Yellow fastext\">---</button>\n    <button class=\"fbtn fbtn-cyan\"   id=\"ft-cyan\"   aria-label=\"Cyan fastext\">---</button>\n  </div>\n\n  <div id=\"torch-row\">\n    <span id=\"torch-label\">Torch:</span>\n    <button id=\"torch-btn\" aria-pressed=\"false\" aria-label=\"Toggle torch mode\">Off</button>\n  </div>\n</div>\n\n<div id=\"footer\">\n  Data: USGS, NASA EONET, Open-Meteo (<a href=\"/p/199\" target=\"_blank\">CC BY 4.0</a>).\n  Also as text: <a href=\"/p/100.txt\">/p/100.txt</a>\n</div>\n\n<!-- Visually hidden aria-live text block -->\n<pre id=\"a11y-text\" aria-live=\"polite\" aria-atomic=\"true\"></pre>\n\n<script>\n(function(){\n'use strict';\n\n// ---------------------------------------------------------------------------\n// State\n// ---------------------------------------------------------------------------\nvar curPage   = 100;\nvar curSub    = 1;\nvar curSubs   = 1;\nvar curLinks  = [];\nvar digits    = '';   // 0-3 chars being typed\nvar torchOn   = false;\nvar torchRow  = 12;   // 0-23, beam centre\nvar fetchCtrl = null; // AbortController for in-flight fetch\n\n// ---------------------------------------------------------------------------\n// Colour map\n// ---------------------------------------------------------------------------\nvar COL = {\n  white:   '#ffffff',\n  yellow:  '#ffff00',\n  cyan:    '#00ffff',\n  green:   '#00ff00',\n  red:     '#ff0000',\n  magenta: '#ff00ff',\n  blue:    '#4d7cff'\n};\n\n// ---------------------------------------------------------------------------\n// DOM refs\n// ---------------------------------------------------------------------------\nvar screen      = document.getElementById('screen');\nvar overlay     = document.getElementById('torch-overlay');\nvar digitDisp   = document.getElementById('digit-display');\nvar placeInput  = document.getElementById('place-input');\nvar placeBtn    = document.getElementById('place-btn');\nvar placeName   = document.getElementById('place-name');\nvar torchBtn    = document.getElementById('torch-btn');\nvar a11yText    = document.getElementById('a11y-text');\nvar screenWrap  = document.getElementById('screen-wrap');\nvar ftBtns      = {\n  red:    document.getElementById('ft-red'),\n  green:  document.getElementById('ft-green'),\n  yellow: document.getElementById('ft-yellow'),\n  cyan:   document.getElementById('ft-cyan')\n};\n\n// ---------------------------------------------------------------------------\n// Build the 24 row divs once\n// ---------------------------------------------------------------------------\nvar rowDivs = [];\nfor (var i = 0; i < 24; i++) {\n  var d = document.createElement('div');\n  d.className = 'row';\n  var sp = document.createElement('span');\n  d.appendChild(sp);\n  screen.appendChild(d);\n  rowDivs.push(sp);\n}\n\n// ---------------------------------------------------------------------------\n// Render page data into the screen\n// ---------------------------------------------------------------------------\nfunction renderPage(data) {\n  var rows   = data.rows   || [];\n  var colors = data.colors || [];\n  curLinks = data.links || [];\n  curSubs  = data.subs  || 1;\n  curSub   = data.sub   || 1;\n\n  var plainText = '';\n  for (var i = 0; i < 24; i++) {\n    var text  = rows[i]   || '                                        ';\n    var color = colors[i] || 'white';\n    var col   = COL[color] || '#ffffff';\n    rowDivs[i].textContent  = text;\n    rowDivs[i].style.color  = col;\n    plainText += text + '\\n';\n  }\n\n  // Aria-live text\n  a11yText.textContent = (data.title || '') + '\\n' + plainText;\n\n  // Fastext labels\n  var colorOrder = ['red','green','yellow','cyan'];\n  colorOrder.forEach(function(c){ ftBtns[c].textContent = '---'; ftBtns[c].dataset.num = ''; });\n  curLinks.forEach(function(lk){\n    if (ftBtns[lk.color]) {\n      ftBtns[lk.color].textContent = lk.num + ' ' + (lk.label || '');\n      ftBtns[lk.color].dataset.num = lk.num;\n    }\n  });\n\n  // Place name from cookie / data\n  if (data.placeName) placeName.textContent = data.placeName;\n\n  drawTorch();\n}\n\n// ---------------------------------------------------------------------------\n// Fetch a page\n// ---------------------------------------------------------------------------\nfunction loadPage(num, sub, extra) {\n  sub  = sub  || 1;\n  extra = extra || '';\n  if (fetchCtrl) fetchCtrl.abort();\n  fetchCtrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;\n\n  var url = '/p/' + String(num).padStart(3,'0') + '.json?s=' + sub + extra;\n  var opts = { credentials: 'include' };\n  if (fetchCtrl) opts.signal = fetchCtrl.signal;\n\n  fetch(url, opts)\n    .then(function(r){ return r.json(); })\n    .then(function(data){\n      curPage = num;\n      curSub  = sub;\n      curSubs = data.subs || 1;\n      renderPage(data);\n      var histUrl = '/p/' + String(num).padStart(3,'0') + (sub > 1 ? '?s=' + sub : '');\n      if (window.location.pathname !== '/p/' + String(num).padStart(3,'0')) {\n        history.pushState({ num:num, sub:sub }, '', histUrl);\n      }\n    })\n    .catch(function(e){\n      if (e && e.name === 'AbortError') return;\n      showError('Failed to load page ' + num);\n    });\n}\n\nfunction showError(msg) {\n  var blank = '                                        ';\n  for (var i = 0; i < 24; i++) {\n    rowDivs[i].textContent = blank;\n    rowDivs[i].style.color = '#ffffff';\n  }\n  rowDivs[1].textContent = 'ERROR                                   ';\n  rowDivs[1].style.color = '#ff0000';\n  rowDivs[3].textContent = (msg + blank).slice(0, 40);\n  rowDivs[3].style.color = '#ffffff';\n  a11yText.textContent = 'Error: ' + msg;\n}\n\n// ---------------------------------------------------------------------------\n// Digit entry\n// ---------------------------------------------------------------------------\nfunction pushDigit(d) {\n  if (digits.length >= 3) digits = '';\n  digits += d;\n  digitDisp.textContent = (digits + '---').slice(0, 3);\n  if (digits.length === 3) {\n    var num = parseInt(digits, 10);\n    digits = '';\n    digitDisp.textContent = '---';\n    loadPage(num, 1);\n  }\n}\n\nfunction clearDigits() {\n  digits = '';\n  digitDisp.textContent = '---';\n}\n\n// ---------------------------------------------------------------------------\n// Keyboard\n// ---------------------------------------------------------------------------\ndocument.addEventListener('keydown', function(e) {\n  // Don't capture when typing in the place input\n  if (document.activeElement === placeInput) return;\n\n  if (e.key >= '0' && e.key <= '9') { e.preventDefault(); pushDigit(e.key); return; }\n  if (e.key === 'Backspace') { e.preventDefault(); clearDigits(); return; }\n  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {\n    e.preventDefault();\n    if (curSub < curSubs) loadPage(curPage, curSub + 1);\n    return;\n  }\n  if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {\n    e.preventDefault();\n    if (curSub > 1) loadPage(curPage, curSub - 1);\n    return;\n  }\n  if (e.key === 'F1' || e.key === 'r') { e.preventDefault(); fastextGo('red');    return; }\n  if (e.key === 'F2' || e.key === 'g') { e.preventDefault(); fastextGo('green');  return; }\n  if (e.key === 'F3' || e.key === 'y') { e.preventDefault(); fastextGo('yellow'); return; }\n  if (e.key === 'F4' || e.key === 'c') { e.preventDefault(); fastextGo('cyan');   return; }\n  // Torch beam move with keyboard\n  if (torchOn) {\n    if (e.key === 'ArrowUp')   { e.preventDefault(); torchRow = Math.max(0,  torchRow - 1); drawTorch(); return; }\n    if (e.key === 'ArrowDown') { e.preventDefault(); torchRow = Math.min(23, torchRow + 1); drawTorch(); return; }\n  }\n});\n\nfunction fastextGo(color) {\n  var btn = ftBtns[color];\n  if (btn && btn.dataset.num) loadPage(parseInt(btn.dataset.num, 10), 1);\n}\n\n// ---------------------------------------------------------------------------\n// Keypad buttons\n// ---------------------------------------------------------------------------\ndocument.getElementById('keypad').addEventListener('click', function(e) {\n  var btn = e.target.closest('.kbtn');\n  if (!btn) return;\n  var d = btn.dataset.d;\n  if (d !== undefined) { pushDigit(d); return; }\n  if (btn.id === 'btn-back') { clearDigits(); return; }\n  if (btn.id === 'btn-go') {\n    if (digits.length > 0) {\n      var num = parseInt(digits.padEnd(3,'0'), 10);\n      digits = '';\n      digitDisp.textContent = '---';\n      loadPage(num, 1);\n    }\n    return;\n  }\n});\n\ndocument.getElementById('btn-prev').addEventListener('click', function(){\n  if (curSub > 1) loadPage(curPage, curSub - 1);\n});\ndocument.getElementById('btn-next').addEventListener('click', function(){\n  if (curSub < curSubs) loadPage(curPage, curSub + 1);\n});\n\n// Fastext buttons\n['red','green','yellow','cyan'].forEach(function(c){\n  ftBtns[c].addEventListener('click', function(){ fastextGo(c); });\n});\n\n// ---------------------------------------------------------------------------\n// Place\n// ---------------------------------------------------------------------------\nplaceBtn.addEventListener('click', setPlace);\nplaceInput.addEventListener('keydown', function(e){ if (e.key === 'Enter') setPlace(); });\n\nfunction setPlace() {\n  var val = placeInput.value.trim();\n  if (!val) return;\n  // Determine if it's lat,lon or a name\n  var isCoord = /^-?\\d+(\\.\\d+)?\\s*,\\s*-?\\d+(\\.\\d+)?$/.test(val);\n  var extra;\n  if (isCoord) {\n    var parts = val.split(',');\n    extra = '&lat=' + encodeURIComponent(parts[0].trim()) + '&lon=' + encodeURIComponent(parts[1].trim());\n  } else {\n    extra = '&place=' + encodeURIComponent(val);\n  }\n  // Load page 101 with the place param; cookie will be set by server\n  var url = '/p/101.json?s=1' + extra;\n  fetch(url, { credentials: 'include' })\n    .then(function(r){ return r.json(); })\n    .then(function(data){\n      curPage = 101; curSub = 1;\n      renderPage(data);\n      // Extract place name from the rendered rows (row 2 starts \"Place: ...\")\n      var rows = data.rows || [];\n      for (var i = 0; i < rows.length; i++) {\n        var m = rows[i].match(/^Place:\\s*(.+?)\\s*$/);\n        if (m) { placeName.textContent = m[1].trim(); break; }\n      }\n      history.pushState({ num:101, sub:1 }, '', '/p/101');\n    })\n    .catch(function(){ showError('Could not set place'); });\n}\n\n// ---------------------------------------------------------------------------\n// Torch mode\n// ---------------------------------------------------------------------------\ntorchBtn.addEventListener('click', function(){\n  torchOn = !torchOn;\n  document.body.classList.toggle('torch-on', torchOn);\n  torchBtn.textContent = torchOn ? 'On' : 'Off';\n  torchBtn.setAttribute('aria-pressed', String(torchOn));\n  drawTorch();\n});\n\n// Pointer / touch moves the beam\nscreenWrap.addEventListener('mousemove', function(e){\n  if (!torchOn) return;\n  var rect = screenWrap.getBoundingClientRect();\n  var y = e.clientY - rect.top;\n  torchRow = Math.floor((y / rect.height) * 24);\n  torchRow = Math.max(0, Math.min(23, torchRow));\n  drawTorch();\n});\nscreenWrap.addEventListener('touchmove', function(e){\n  if (!torchOn) return;\n  e.preventDefault();\n  var rect = screenWrap.getBoundingClientRect();\n  var y = e.touches[0].clientY - rect.top;\n  torchRow = Math.floor((y / rect.height) * 24);\n  torchRow = Math.max(0, Math.min(23, torchRow));\n  drawTorch();\n}, { passive: false });\n\nfunction drawTorch() {\n  if (!torchOn) {\n    // Remove dim from all rows\n    rowDivs.forEach(function(r){ r.parentNode.style.opacity = ''; });\n    return;\n  }\n  // Dim rows outside the 3-row band\n  for (var i = 0; i < 24; i++) {\n    var row = rowDivs[i].parentNode;\n    var inBeam = (i >= torchRow - 1 && i <= torchRow + 1);\n    row.style.opacity = inBeam ? '1' : '0.25';\n  }\n}\n\n// ---------------------------------------------------------------------------\n// Browser back/forward\n// ---------------------------------------------------------------------------\nwindow.addEventListener('popstate', function(e){\n  if (e.state && e.state.num) {\n    loadPage(e.state.num, e.state.sub || 1);\n  }\n});\n\n// ---------------------------------------------------------------------------\n// Resize: keep canvas in sync (torch overlay sized to match wrapper)\n// ---------------------------------------------------------------------------\nfunction syncCanvas() {\n  overlay.width  = screenWrap.offsetWidth;\n  overlay.height = screenWrap.offsetHeight;\n}\nwindow.addEventListener('resize', syncCanvas);\n\n// ---------------------------------------------------------------------------\n// Font size: ensure 40 chars fill the row exactly\n// We compute cell width = wrapper_width / 40, set font-size to that * 0.6\n// (approximate monospace em ~0.6 of font-size; clamp in CSS handles extremes)\n// ---------------------------------------------------------------------------\nfunction syncFont() {\n  var w = screenWrap.offsetWidth;\n  var h = screenWrap.offsetHeight;\n  // font-size such that 40 chars fill width\n  // monospace char width \u2248 0.6 * font-size; so font-size = w / (40 * 0.6)\n  var fs = Math.max(6, Math.min(22, (w / 40) * 0.6));\n  screen.style.fontSize = fs + 'px';\n  // Also row height should be h/24\n  // We use grid so that's automatic; just ensure no overflow\n}\nwindow.addEventListener('resize', syncFont);\n\n// ---------------------------------------------------------------------------\n// Initial load\n// ---------------------------------------------------------------------------\n(function init(){\n  syncCanvas();\n  syncFont();\n\n  // Determine initial page from URL path /p/<num>\n  var m = window.location.pathname.match(/\\/p\\/(\\d{3})/);\n  var initPage = m ? parseInt(m[1], 10) : 100;\n  var initSub  = 1;\n  var sp = new URLSearchParams(window.location.search).get('s');\n  if (sp) initSub = parseInt(sp, 10) || 1;\n\n  // Pass any place params from URL query\n  var extra = '';\n  var qp = new URLSearchParams(window.location.search);\n  if (qp.get('place')) extra = '&place=' + encodeURIComponent(qp.get('place'));\n  else if (qp.get('lat') && qp.get('lon')) {\n    extra = '&lat=' + encodeURIComponent(qp.get('lat')) + '&lon=' + encodeURIComponent(qp.get('lon'));\n  }\n\n  history.replaceState({ num:initPage, sub:initSub }, '', window.location.href);\n  loadPage(initPage, initSub, extra);\n})();\n\n})();\n</script>\n</body>\n</html>\n";
